const own = Object.prototype.hasOwnProperty;

function locationAt(source: string, offset: number): Location {
  let line = 1;
  let column = 1;
  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
  return { line, column };
}

function syntaxError(message: string, location: Location): Error {
  return new Error(`${message} at line ${location.line}, column ${location.column}`);
}

function requirePath(path: string, kind: string, location: Location): string {
  if (!path) throw syntaxError(`${kind} requires a path`, location);
  if (path.split(".").some((part) => part.length === 0)) {
    throw syntaxError(`Invalid path '${path}'`, location);
  }
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: OpenBlock[] = [];
  let current = root;
  let offset = 0;

  while (offset < template.length) {
    const start = template.indexOf("{{", offset);
    if (start === -1) {
      current.push({ type: "text", value: template.slice(offset) });
      break;
    }
    if (start > offset) current.push({ type: "text", value: template.slice(offset, start) });

    const triple = template.startsWith("{{{", start);
    const close = triple ? "}}}" : "}}";
    const contentStart = start + (triple ? 3 : 2);
    const end = template.indexOf(close, contentStart);
    const location = locationAt(template, start);
    if (end === -1) throw syntaxError("Unclosed tag", location);

    const tag = template.slice(contentStart, end).trim();
    offset = end + close.length;

    if (triple) {
      current.push({
        type: "value",
        path: requirePath(tag, "Interpolation", location),
        escaped: false,
        location,
      });
      continue;
    }

    if (tag.startsWith("!")) continue;

    if (tag.startsWith("#")) {
      const declaration = tag.slice(1).trim();
      const space = declaration.search(/\s/);
      const name = space === -1 ? declaration : declaration.slice(0, space);
      const path = space === -1 ? "" : declaration.slice(space).trim();
      if (name !== "if" && name !== "each") {
        throw syntaxError(`Unknown block '${name || declaration}'`, location);
      }
      const node: BlockNode = {
        type: name,
        path: requirePath(path, `#${name}`, location),
        body: [],
        alternate: [],
        location,
      };
      current.push(node);
      stack.push({ node, parent: current, inAlternate: false });
      current = node.body;
      continue;
    }

    if (tag === "else") {
      const open = stack.at(-1);
      if (!open) throw syntaxError("else outside a block", location);
      if (open.inAlternate) throw syntaxError("Duplicate else", location);
      open.inAlternate = true;
      current = open.node.alternate;
      continue;
    }

    if (tag.startsWith("/")) {
      const name = tag.slice(1).trim();
      const open = stack.at(-1);
      if (!open) throw syntaxError(`Unexpected closing block '/${name}'`, location);
      if (name !== open.node.type) {
        throw syntaxError(`Mismatched closing block '/${name}'; expected '/${open.node.type}'`, location);
      }
      stack.pop();
      current = open.parent;
      continue;
    }

    current.push({
      type: "value",
      path: requirePath(tag, "Interpolation", location),
      escaped: true,
      location,
    });
  }

  const unclosed = stack.at(-1);
  if (unclosed) {
    throw syntaxError(`Unclosed block '#${unclosed.node.type}'`, unclosed.node.location);
  }
  return root;
}

type Lookup = { found: boolean; value: unknown };

function lookupFrom(base: unknown, parts: string[]): Lookup {
  let value = base;
  for (const part of parts) {
    if ((typeof value !== "object" || value === null) && typeof value !== "function") {
      return { found: false, value: undefined };
    }
    const object = value as Record<string, unknown>;
    if (!own.call(object, part)) return { found: false, value: undefined };
    value = object[part];
  }
  return { found: true, value };
}

function resolve(path: string, root: unknown, contexts: EachContext[]): unknown {
  const context = contexts.at(-1);
  if (path === "this") return context ? context.value : root;
  if (path === "@index") return context ? context.index : undefined;

  if (path.startsWith("this.")) {
    if (!context) return undefined;
    return lookupFrom(context.value, path.slice(5).split(".")).value;
  }

  const parts = path.split(".");
  if (context) {
    const local = lookupFrom(context.value, parts);
    if (local.found) return local.value;
  }
  return lookupFrom(root, parts).value;
}

function isTruthy(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return value !== "" && value !== 0 && value !== false && value !== null && value !== undefined;
}

function scalar(value: unknown, path: string, location: Location): string {
  if (value === null || value === undefined) return "";
  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
    case "bigint":
    case "symbol":
      return String(value);
    default:
      throw syntaxError(`Value '${path}' is not scalar and cannot be rendered`, location);
  }
