function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], root: unknown, contexts: EachContext[]): string {
  let output = "";
  for (const node of nodes) {
    if (node.type === "text") {
      output += node.value;
    } else if (node.type === "value") {
      const value = scalar(resolve(node.path, root, contexts), node.path, node.location);
      output += node.escaped ? escapeHtml(value) : value;
    } else if (node.type === "if") {
      const branch = isTruthy(resolve(node.path, root, contexts)) ? node.body : node.alternate;
      output += renderNodes(branch, root, contexts);
    } else {
      const value = resolve(node.path, root, contexts);
      if (Array.isArray(value) && value.length > 0) {
        for (let index = 0; index < value.length; index++) {
          contexts.push({ value: value[index], index });
          try {
            output += renderNodes(node.body, root, contexts);
          } finally {
            contexts.pop();
          }
        }
      } else {
        output += renderNodes(node.alternate, root, contexts);
      }
    }
  }
  return output;
}

