async function main(): Promise<void> {
  const [templatePath, dataPath, ...extra] = Bun.argv.slice(2);
  if (!templatePath || !dataPath || extra.length > 0) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const template = await Bun.file(templatePath).text();
  const json = await Bun.file(dataPath).text();
  let data: unknown;
  try {
    data = JSON.parse(json);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid JSON in '${dataPath}': ${detail}`);
  }

  await Bun.write(Bun.stdout, render(template, data));
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error(message);
  process.exitCode = 1;
});
import { describe, expect, test } from "bun:test";
import { render } from "../src/engine.ts";

describe("interpolation", () => {
  test("resolves paths, escapes HTML, and preserves whitespace", () => {
    expect(render("  Hi {{user.name}}!\n{{missing}}", { user: { name: `<A & "B" 'C'>` } }))
      .toBe("  Hi &lt;A &amp; &quot;B&quot; &#39;C&#39;&gt;!\n");
  });

  test("supports raw values and comments", () => {
    expect(render("{{{html}}}{{! hidden }}done", { html: "<b>x</b>" })).toBe("<b>x</b>done");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("x {{value}}", { value: { x: 1 } })).toThrow(/not scalar.*line 1, column 3/);
  });
});

describe("blocks", () => {
  test("implements the specified truthiness", () => {
    for (const value of ["", 0, false, null, undefined, []]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
    }
    for (const value of ["x", 1, true, {}, [0], Number.NaN]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("yes");
    }
  });

  test("supports nested each, indexes, local lookup, and root fallback", () => {
    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each items}}{{@index}}={{this}};{{else}}empty{{/each}}]{{else}}none{{/each}}";
    const data = { title: "root", groups: [{ name: "A", items: ["x", "y"] }, { name: "B", items: [] }] };
    expect(render(template, data)).toBe("[A/root:0=x;1=y;][B/root:empty]");
  });

  test("each else handles missing and non-array values", () => {
    expect(render("{{#each rows}}x{{else}}empty{{/each}}", { rows: "no" })).toBe("empty");
  });
});

